import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"本地模型是什么","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1786093688000}'),d={name:"index.md"};function l(i,t,n,s,h,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="本地模型是什么" tabindex="-1">本地模型是什么 <a class="header-anchor" href="#本地模型是什么" aria-label="Permalink to &quot;本地模型是什么&quot;">​</a></h1><p>MiniTavern 是 <strong>BYOK（自备密钥）</strong> 客户端：对话请求发往你配置的 API 地址，不会强制绑定某一家云厂商。<br> 「本地模型」指在你自己的电脑上运行大语言模型，再用手机上的 MiniTavern 通过局域网连接，实现：</p><ul><li>不按 token 向云端付费（电费与硬件除外）</li><li>对话内容主要留在你的设备与局域网内</li><li>可自由更换开源角色扮演模型</li></ul><blockquote><p>MiniTavern <strong>本身不在手机上跑大模型</strong>。模型跑在电脑（或其它能提供 OpenAI 兼容 API 的机器）上，App 只负责角色卡、世界书与聊天界面。</p></blockquote><h2 id="你需要准备什么" tabindex="-1">你需要准备什么 <a class="header-anchor" href="#你需要准备什么" aria-label="Permalink to &quot;你需要准备什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>建议</th></tr></thead><tbody><tr><td>电脑</td><td>Windows / macOS；内存建议 <strong>16GB+</strong>（8GB 只能跑很小的量化模型）</td></tr><tr><td>显卡（可选）</td><td>NVIDIA / Apple Silicon 会明显更快；纯 CPU 也能跑，但更慢</td></tr><tr><td>网络</td><td>手机与电脑连 <strong>同一 Wi‑Fi</strong>（不要用访客网络隔离）</td></tr><tr><td>时间</td><td>第一次约 <strong>30–60 分钟</strong>（下载安装包与模型最耗时）</td></tr></tbody></table><h2 id="选哪条路径" tabindex="-1">选哪条路径 <a class="header-anchor" href="#选哪条路径" aria-label="Permalink to &quot;选哪条路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>适合谁</th><th>特点</th></tr></thead><tbody><tr><td><a href="./ollama/install">Ollama</a></td><td>愿意用命令行、要省事</td><td>安装快、<code>ollama pull</code> 一键下模型、默认端口 <code>11434</code></td></tr><tr><td><a href="./lmstudio/install">LM Studio</a></td><td>更喜欢图形界面</td><td>点选下载模型、内置 Local Server、默认端口常见为 <code>1234</code></td></tr></tbody></table><p>两条路径最后都要在 MiniTavern 里填 <strong>自定义（OpenAI 兼容）</strong> 连接，见 <a href="./connect-app/minitavern">在 MiniTavern 中配置</a>。</p><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><ol><li><a href="./quickstart">30 分钟通关</a> — 先跑通一次对话</li><li>按你选的工具细读 Ollama 或 LM Studio 章节</li><li>卡住时查 <a href="./troubleshoot">排错对照表</a></li><li>App 完整用法见 <a href="./manual/">使用手册</a></li></ol><h2 id="关键提醒" tabindex="-1">关键提醒 <a class="header-anchor" href="#关键提醒" aria-label="Permalink to &quot;关键提醒&quot;">​</a></h2><ul><li>手机里填的地址必须是电脑的 <strong>局域网 IP</strong>（如 <code>192.168.1.8</code>），<strong>不要</strong>填 <code>localhost</code> / <code>127.0.0.1</code>（那是「本机自己」，在手机上指的是手机自己）。</li><li>Base URL 通常要以 <code>/v1</code> 结尾，例如 <code>http://192.168.1.8:11434/v1</code>。</li><li>MiniTavern Android 已允许局域网明文 HTTP；仍需关闭电脑防火墙对端口的拦截。</li></ul>',13)])])}const b=a(d,[["render",l]]);export{u as __pageData,b as default};
